import json,base64
out=Path('outputs/florida_coastal_atlas');towns=json.loads((out/'town_registry.json').read_text());b64=base64.b64encode((out/'florida_coastal_complete_atlas.glb').read_bytes()).decode()
html='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Florida Coastal — The Whole Coast</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#ece8dc;color:#3f5143;font:14px system-ui,sans-serif}main{height:100vh;display:grid;grid-template-columns:280px 1fr}aside{background:#f6f2e7;display:flex;flex-direction:column;padding:25px 20px;min-height:0;gap:14px;border-right:1px solid #d4d4c4}h1{font:500 25px Georgia,serif;margin:0}h2{font:500 23px Georgia,serif;margin:0 0 6px}p{margin:0;line-height:1.5}.small{font-size:12px;color:#687566}input,select,button{font:inherit;border:1px solid #c8cdbe;border-radius:7px;padding:10px;background:#fffdf6;color:inherit}button,a{cursor:pointer}button:hover,button.active{background:#dce4d3}#towns{overflow:auto;display:flex;flex-direction:column;gap:5px;flex:1;min-height:100px}#towns button{text-align:left;border:0;background:transparent;padding:9px}#towns button.active{background:#dce4d3}#towns button span{display:block;font-size:11px;color:#73806d}.stage{position:relative;min-width:0;overflow:hidden}canvas{display:block;width:100%;height:100%;touch-action:none}.card{position:absolute;left:25px;top:25px;background:#fffdf3ed;border:1px solid #e0dfd0;border-radius:12px;padding:17px 20px;max-width:410px;pointer-events:none}.card a,.card button{pointer-events:auto}.card p{font-size:13px}.card a[hidden]{display:none}.card a{display:inline-block;margin-top:12px;color:#496a51}.actions{position:absolute;right:20px;bottom:45px;display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;max-width:calc(100% - 40px)}#loading{position:absolute;inset:0;display:grid;place-items:center;background:#ece8dc;font:24px Georgia,serif;z-index:5}#credit{position:absolute;left:22px;bottom:18px;max-width:95%;font-size:11px;color:#536450}.chip{display:inline-block;font-size:11px;letter-spacing:.08em;text-transform:uppercase;margin-bottom:7px}a{color:#496a51}@media(max-width:700px){main{grid-template-columns:1fr;grid-template-rows:205px 1fr}aside{padding:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px;border-bottom:1px solid #cdd3c3}h1{font-size:20px}.intro{grid-column:1/3}#towns{grid-column:1/3;display:flex;flex-direction:row;min-height:45px;overflow:auto}#towns button{white-space:nowrap}.card{left:12px;top:12px;max-width:calc(100% - 24px);padding:11px}h2{font-size:20px}.actions{bottom:14px;right:12px}#credit{display:none}aside>.small{display:none}}</style>
<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/"}}</script></head>
<body><main><aside><div class="intro"><span class="chip">Florida Coastal</span><h1>The whole coast</h1><p class="small">106 towns. One connected coastline.</p></div><input id="search" aria-label="Find a town" placeholder="Find a town…"><select id="region" aria-label="Coastal area"><option value="">All 15 coastal areas</option></select><div id="towns" aria-label="Towns"></div><p class="small">Drag to orbit. Scroll to zoom. Right-drag to pan.</p><p class="small">Published coastline and town anchors. Enlarged artistic landmarks and neighborhoods.</p></aside><section class="stage" id="stage" aria-label="Three dimensional Florida coastal atlas"><div id="loading">Opening the coast…</div><div class="card"><span id="eyebrow" class="chip">Geographic atlas</span><h2 id="title">Florida, coast to coast</h2><p id="detail">Choose a town to explore its center, local landmarks, and suburban neighborhoods.</p><a id="download" hidden>Download town model</a></div><div class="actions"><button id="whole">Whole coast</button><button id="area">Coastal area</button><button id="center">Town center</button><button id="suburbs">Town + suburbs</button><button id="top">Top view</button></div><div id="credit">Coast + roads: U.S. Census • Lakes: Natural Earth • Towns: FloridaCoastal.co</div></section></main>
<script type="module">
import * as THREE from 'three';import {OrbitControls} from 'three/addons/controls/OrbitControls.js';import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
const towns=__TOWNS__;const data='__GLB__';
const stage=document.getElementById('stage'),scene=new THREE.Scene();scene.background=new THREE.Color('#eae7db');
const renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.0;stage.prepend(renderer.domElement);
const camera=new THREE.PerspectiveCamera(36,1,.005,10000);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.1;controls.maxPolarAngle=Math.PI*.49;controls.minDistance=.08;controls.maxDistance=3000;
scene.add(new THREE.HemisphereLight(0xfff9e5,0x9aab8c,1.0));const sun=new THREE.DirectionalLight(0xfff5df,1.8);sun.position.set(-300,600,200);scene.add(sun);
let selected=null,model=null,ready=false,viewSpan=720;const byid=new Map(towns.map(t=>[t.id,t]));
const regionSelect=document.getElementById('region'),list=document.getElementById('towns');const areas=[...new Map(towns.map(t=>[t.area_id,t.area_name])).entries()];for(const [id,name] of areas){const op=document.createElement('option');op.value=id;op.textContent=name;regionSelect.append(op)}
function drawlist(){list.replaceChildren();const term=document.getElementById('search').value.toLowerCase();for(const t of towns.filter(t=>(!regionSelect.value||t.area_id===regionSelect.value)&&t.name.toLowerCase().includes(term)).sort((a,b)=>a.name.localeCompare(b.name))){const btn=document.createElement('button');btn.dataset.town=t.id;btn.className=selected?.id===t.id?'active':'';btn.textContent=t.name;const small=document.createElement('span');small.textContent=t.area_name;btn.append(small);btn.onclick=()=>choose(t.id);list.append(btn)}}
function fit(cx,cy,span,tilt=true){viewSpan=span;controls.target.set(cx,.08,-cy);const distance=span/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))*1.15/Math.min(1,camera.aspect);const direction=new THREE.Vector3(.06,tilt?1:1.6,tilt?.8:.001).normalize();camera.position.copy(controls.target).addScaledVector(direction,distance);camera.near=Math.max(.002,span/50);camera.far=Math.max(100,span*15);camera.updateProjectionMatrix();controls.update()}
function whole(){selected=null;document.getElementById('title').textContent='Florida, coast to coast';document.getElementById('eyebrow').textContent='Geographic atlas';document.getElementById('detail').textContent='106 towns along 15 coastal areas. Coastline and town anchors stay in their published locations.';document.getElementById('download').hidden=true;fit(23,420,950);drawlist();window.atlasSelection=null}
function choose(id){const t=byid.get(id);if(!t)return;selected=t;document.getElementById('title').textContent=t.name;document.getElementById('eyebrow').textContent=t.area_name;document.getElementById('detail').textContent=t.landmarks.join(' · ');const dl=document.getElementById('download');dl.hidden=false;dl.href='towns/'+t.id+'.glb';dl.download=t.id+'.glb';fit(t.x,t.y,Math.max(.35,t.display_scale*52));drawlist();window.atlasSelection=t.id}
function regionView(){const id=regionSelect.value||selected?.area_id;if(!id){whole();return}const ts=towns.filter(t=>t.area_id===id);const xs=ts.map(t=>t.x),ys=ts.map(t=>t.y);fit((Math.min(...xs)+Math.max(...xs))/2,(Math.min(...ys)+Math.max(...ys))/2,Math.max(30,Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys))*1.25);document.getElementById('title').textContent=ts[0].area_name;document.getElementById('detail').textContent=ts.length+' coastal towns, connected by the geographic road network.'}
document.getElementById('search').oninput=drawlist;regionSelect.onchange=()=>{drawlist();regionView()};document.getElementById('whole').onclick=whole;document.getElementById('area').onclick=regionView;document.getElementById('center').onclick=()=>{if(selected)fit(selected.x,selected.y,selected.display_scale*28)};document.getElementById('suburbs').onclick=()=>{if(selected)fit(selected.x,selected.y,selected.display_scale*130)};document.getElementById('top').onclick=()=>{fit(controls.target.x,-controls.target.z,viewSpan,false)};
const ring=new THREE.Mesh(new THREE.RingGeometry(.95,1,64),new THREE.MeshBasicMaterial({color:0x637e55,side:THREE.DoubleSide,transparent:true,opacity:.55}));ring.rotation.x=-Math.PI/2;ring.visible=false;scene.add(ring);
new ResizeObserver(()=>{const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}).observe(stage);
function animate(){requestAnimationFrame(animate);controls.update();if(selected){ring.visible=false;ring.position.set(selected.x,.045,-selected.y);ring.scale.setScalar(selected.display_scale*56)}else ring.visible=false;renderer.render(scene,camera)}
window.atlasChoose=choose;window.atlasWhole=whole;window.atlasScreenshot=()=>renderer.domElement.toDataURL('image/png');window.atlasStats=()=>({ready,selected:selected?.id,drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,towns:towns.length});
try{const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));new GLTFLoader().parse(bytes.buffer,'',g=>{model=g.scene;model.traverse(o=>{if(o.isMesh && (o.name+' '+o.parent?.name).includes('Geography')){const mats=Array.isArray(o.material)?o.material:[o.material];const basic=mats.map(m=>new THREE.MeshBasicMaterial({color:m.color.clone(),side:THREE.DoubleSide,toneMapped:false}));o.material=Array.isArray(o.material)?basic:basic[0]}});scene.add(model);ready=true;window.atlasReady=true;document.getElementById('loading').style.display='none';whole();animate()},error=>{document.getElementById('loading').textContent='The model could not open: '+error.message;console.error(error)})}catch(error){document.getElementById('loading').textContent='Unable to initialize the map: '+error.message}
drawlist();
</script></body></html>'''
html=html.replace('__TOWNS__',json.dumps(towns,separators=(',',':'))).replace('__GLB__',b64)
(out/'explore_coast.html').write_text(html)
print('Viewer saved',len(html))
